    'cli.headless.permission_hint' => '  提示：未指定模式的 `-p` 執行會以詢問 `default` 模式啟動；無人值守的詢問無人可回答，因此會安全失敗。腳本執行可指定 --permission-mode bypass-permissions（或 accept-edits）以繼續。',
    'cli.help.screen' => <<<'TXT'
CandyCode — 終端機 AI 程式碼助理。

用法：
  candy-code                       啟動互動式 TUI（預設）
  candy-code <dir>                 以 <dir> 為根目錄啟動 TUI，該目錄必須
                                   存在（僅限作為第一個引數）
  candy-code [<dir>] <words…>      啟動 TUI 並將文字作為其
                                   第一個提示送出，例如 candy-code fix the bug
  candy-code -c                    繼續最近的工作階段
  candy-code --resume [<id>]       恢復已儲存的工作階段（無 id 則顯示選單）
  candy-code -p <prompt>           執行單一提示後退出（一次性）
  candy-code run "<prompt>"        -p "<prompt>" 的別名（一次性模式）
  candy-code --output-format json  輸出機器可讀 JSON（一次性）
  candy-code --worktree [<name>]   在此工作階段使用專屬 git worktree
                                   執行（不存在則建立）

子命令（均不開啟 TUI，也不需要供應商、API 金鑰或
終端機；除 serve 與 mcp serve 會持續執行至
停止外，其餘均回答後退出 — 而 attach 為兩者之例外：它在執行中的伺服器
工作階段上執行 TUI；acp 為編輯器執行回合，直至編輯器斷線）：
  bundles list           列出此目錄可見的插件套件：名稱、
                         版本、層級，以及各套件包含的介面 —
                         包括 candy-code 拒絕執行的 hooks 與
                         .mcp.json。
  bundles install <src>  複製套件目錄，或以深度一 git clone
                         將 git URL 複製到使用者套件根目錄
                         （~/.candy-code/bundles），僅你擁有該目錄。
  doctor                 檢查此安裝並回報所有發現的問題：
                         PHP 版本、工作階段儲存與 serve 所需的擴充
                         功能、設定檔、權限
                         政策、選取的供應商、工作階段資料庫
                         與專案 MCP 設定。任何檢查
                         失敗則以 1 退出。
                         有別於模型可呼叫的 "doctor" 工具，該工具
                         向模型回報終端機的影像協定。
  import claude          預覽匯入 Claude Code 設定：讀取 Claude 的使用者
                         設定檔，以及啟動根目錄下的 .claude 設定檔，
                         當指定 --project 時，將其權限的
                         allow/deny/ask 清單轉換為 permissionRules（較嚴格的一方
                         永遠優先 — deny 勝過 allow），對應模型，並將所有
                         無對應欄位的鍵標記為 skipped。確認前
                         不會寫入任何內容：--yes 直接接受列印的預覽，
                         未指定時則詢問互動式終端機。預覽會列出
                         每一條會擴大免詢問執行範圍的 allow 規則。
  login <provider>       登入一個供應商：claude-code 和 codex 將
                         終端機交給各自的 CLI（token 絕不經過
                         candy-code）；openai、anthropic 和 gemini
                         將金鑰貼入設定檔的 providers 區塊；
                         其餘供應商則標示實際持有憑證者。
  models                 列出此安裝可選用的供應商及各自預設的
                         模型；"*" 標記已選定的
                         項目。
  session list [--all|--archived|--children] [--limit N]
                         列出已儲存的工作階段，釘選的排最前，再按
                         最新排列：id、最後更新、類型、輪次、provider/model
                         及名稱（★ 標記釘選列）。--children 加入
                         子代理與背景列，--archived 加入
                         已歸檔列，--all 兩者皆加入；預設 20 列，
                         除非 --limit 另行指定。
  session show <target>  列印一個工作階段的詳細資訊與逐字稿。
  session rename <target> <title…>
                         重新命名工作階段；目標之後的文字即為
                         標題。
  session delete <target> [--with-children]
                         刪除工作階段。子代理子項一併刪除；
                         分支保留，除非指定 --with-children。
  session pin|unpin|archive|unarchive <target>
                         釘選工作階段（列於最前、永不清除），或
                         歸檔（從預設清單隱藏，但保留）。
                         <target> 為 id、名稱或唯一的 id 前綴。
                         無匹配時退出碼 1，前綴有歧義時退出碼 2
                         （候選項會列出）。
  mcp list               列出 .mcp.json 宣告的 MCP 伺服器，不
                         啟動任何一個。若檔案不存在、解析到
                         專案目錄樹之外，或存在但專案根目錄
                         未受信任，則回報該情況。
  mcp trust              核准此專案目前的 .mcp.json：將根目錄加入
                         "trustedProjectMcp"，並記錄每個伺服器的
                         command、args 與 env，日後任何變更
                         在啟動時將被拒絕，直到重新核准。
                         不啟動任何服務。
  mcp import claude|opencode|claude-project <path> [--write user]
                         轉換外部 MCP 設定並列印對應的
                         .mcp.json 區塊至 stdout。預設僅列印；
                         --write user 將轉換後的
                         條目附加至使用者自己的 ~/.candy-code/mcp.json
                         （名稱衝突時拒絕整個寫入，且
                         專案層級永不寫入）。轉換所做的重新命名
                         會列於 stderr。
  mcp serve [--root PATH]
                         以 stdio 將 candy-code 本身作為 MCP 伺服器：
                         每行輸入一個 JSON-RPC 幀，每行輸出一個回應
                         ，直到 stdin 關閉。工具呼叫執行唯讀
                         清單（Read、Glob、Grep、Ls、RepoMap），限制於
                         工作區根目錄，經過啟動時的 PermissionGate
                         與 PreToolUse 鉤子鏈 — 這是用戶端可
                         啟動的 MCP 伺服器；WebSocket
                         `candy-code serve` 仍不支援 MCP。持續執行
                         直到停止。
  lsp install <language> 安裝指定語言的釘選語言伺服器：
                         npm 套件或經校驗碼驗證的
                         發行二進位檔，安裝至家目錄下的
                         私有安裝根目錄。`lsp list` 回答哪些語言
                         可安裝。
  lsp list               報告每個可安裝語言：其釘選版本、
                         伺服器安裝位置（或未安裝），以及
                         此機器的作業系統與架構是否有
                         對應發行版。不啟動任何服務，
                         不下載任何內容。
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         以最新發行的 candy-code 版本取代此 phar 安裝，
                         換檔前以 sha256 對照發行附檔驗證；
                         執行中的 phar 保留為 <phar>.old，
                         --rollback 精確還原該副本一次。
                         當發行來源釘選了簽章公鑰時，
                         candy-code.phar.minisig 簽章也必須
                         通過驗證（--allow-unsigned 僅跳過
                         該步驟）。--check 僅報告目前與最新
                         版本，有更新可用時退出碼 1。
                         Composer 安裝會被明確拒絕，並指出
                         應改執行的 composer update 指令。開發建置的
                         安裝預設跟隨滾動式 candy-code/dev 發行
                         （發行目標 commit 與戳記 sha 相符時即為最新），
                         --channel 可明確選擇任一
                         更新通道。
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         執行 WebSocket + HTTP 伺服器，供 Web UI 連線，
                         於前景執行直到 Ctrl+C。預設綁定 127.0.0.1:7420
                         並印出一個登入 URL，其一次性
                         代碼會交換為瀏覽器 cookie；每個客戶端
                         都需要它，或 ~/.candy-code/server/token 中的 token，
                         含 loopback。選項：
      --host <ip>        綁定位址（預設 127.0.0.1；localhost 與 ::1
                         亦視為 loopback）。其他位址一律拒絕，
                         除非同時指定 --allow-remote。
      --port <n>         綁定埠號（預設 7420；0 自動選取可用埠）。
      --allow-remote     允許非 loopback 的 --host。未搭配 --tls-cert 與
                         --tls-key 時為純 HTTP：請於前方架設 TLS 反向代理，
                         或直接提供 TLS（見下方）。指定
                         0.0.0.0 或 :: 時，伺服器回應本機所有位址，
                         登入 URL 會列出這些位址。
      --tls-cert <file>  監聽器自身提供 TLS 所用的 PEM 憑證，
                         需與 --tls-key 一併指定。此時登入 URL
                         為 https://，工作階段 cookie 帶有 Secure，
                         明文 http:// 客戶端則完全得不到回應。
      --tls-key <file>   --tls-cert 對應的 PEM 私密金鑰：可讀檔案，
                         不得暴露 group 或 world 權限位，且須與憑證相符。
                         無效或不完整的配對於啟動時即拒絕。
      --allowed-host <list>
                         以逗號分隔的額外主機名稱（或 host:port），
                         伺服器亦會回應，例如本機的 DNS 名稱。
                         可重複指定。
      --allowed-ips <list>
                         以逗號分隔的客戶端 IP 或 CIDR 範圍（如
                         1.2.3.4,10.0.0.0/8）允許連線；其他
                         位址於登入前即回傳 403。Loopback
                         一律允許。未設定：不篩選位址。
                         可重複指定。
      --allowed-origin <list>
                         以逗號分隔的額外瀏覽器來源
                         （http(s)://host[:port]），與伺服器自身
                         來源並列。可重複指定。
      --allow-dir-browse 讓已登入客戶端選擇新工作階段的起始目錄：
                         可列出 --browse-root 下的目錄名稱（不含
                         檔案）。預設關閉。
      --browse-root <dir>
                         --allow-dir-browse 限定的目錄範圍
                         （預設為家目錄）。
      --web-root <dir>   從 <dir> 提供 Web UI，而非安裝的
                         sugarcraft/candy-code-web 套件。
      --no-web           僅提供 API 與 WebSocket，不提供 UI 檔案。
      --allow-bypass     允許工作階段以 bypass-permissions 或 dont-ask
                         模式執行（預設拒絕；伺服器的工作階段以
                         default 啟動，除非 --permission-mode 另有指定）。
      --allow-root       允許以 root 執行（預設拒絕）。
      --detach           背景執行：埠綁定後印出 URL 與 pid
                         即退出；伺服器記錄至
                         狀態目錄中的 server.log。
      --parent-pid <pid> 程序 <pid> 退出時停止伺服器（適用於
                         啟動私有伺服器的編輯器或 TUI）。
                         缺少 ext-pcntl、ext-posix 與
                         ext-ffi 時拒絕啟動（見 doctor）。埠被佔用或
                         同一狀態目錄已有伺服器執行時回傳 1。
  serve status           回報執行中的伺服器：pid、URL、root、執行時間及
                         GET /api/health 是否有回應。無伺服器執行時
                         回傳 1。
  serve stop [--force]   停止伺服器：先發 SIGTERM，最多等 30 秒排空，再發 SIGKILL。
      --force            直接發 SIGKILL。
  serve logs [-f]        印出背景執行伺服器的日誌尾部。
  -f, --follow           持續印出新追加的內容直到停止。
  serve url [--qr]       印出帶有全新一次性代碼的登入 URL。
      --qr              將每個登入 URL 渲染為可掃描的終端機 QR code。
  serve token [--rotate] 印出擁有者 token（bearer 客戶端所傳送）。
      --rotate           替換之；執行中的伺服器保留舊 token 直到
                         重新啟動。
  attach [<session>] [--url <url>]
                         於執行中的 candy-code
                         serve 的工作階段上執行 TUI：伺服器負責每輪對話及其工具，
                         此終端機顯示結果並回答工具提出的
                         權限問題。<session> 為 id、名稱或
                         伺服器工作階段的唯一 id 前綴；
                         未指定則建立新的。目標伺服器即
                         serve status 所回報者，其 token 取自
                         CANDY_CODE_SERVER_TOKEN 或狀態目錄的
                         token 檔案。離開即分離；執行中的輪次
                         繼續進行。無伺服器回應時回傳 1。
      --url <url>        改為附加至 <url> 處的伺服器（即 serve
                         所印出的位址）。
  acp                    以 Agent Client Protocol 代理執行：編輯器
                         （Zed、JetBrains、Neovim）啟動它並透過
                         stdin 與 stdout 以 JSON-RPC 通訊。工作階段於
                         編輯器的專案根目錄，在此以本次
                         安裝的供應商與工具執行，編輯器會回答
                         其權限問題。不適用於終端機：stdout
                         僅傳輸通訊協定（其餘全部送往
                         stderr）。編輯器關閉 stdin 時以 0 退出。
  completion bash|zsh|fish
                         將 shell 補全腳本寫入 stdout，例如
                         eval "$(candy-code completion bash)"。
  usage [7|30|all] [--session <target>]
                         依日期與模型彙整持久消費帳本：
                         與 `/usage` 頁面輸出相同，使用相同的共用
                         折疊。7 與 30 取含今日在內的完整 UTC 日，
                         all（或無運算元）涵蓋整個帳本，
                         超出該範圍的時間窗口會被拒絕而非
                         靜默擴大。--session 以 id、名稱或唯一前綴
                         縮小至單一工作階段；--output-format json
                         輸出頁面所依據的事實對應表。
                         帳本無法讀取時會說明原因並以 1 退出；
                         包含未定價模型的折疊，金額以 ≥ 下界
                         顯示，絕不顯示為單純加總。

選項：
  -p, --prompt <text>    在命令列提供提示（單次模式）
      --output-format <format>
                         輸出格式："text"（預設）、"json" 或
                         "stream-json"（NDJSON 事件，回答在最後）
      --root <dir>       以 <dir> 作為專案根目錄，取代目前
                         目錄。亦接受 --root=<dir>（當 <dir> 以
                         "-" 開頭時應使用此形式）；不可省略。
                         在此指定根目錄同時又作為位置引數
                         會被拒絕，而非讓其中一個靜默生效。
      --config <file>    從 <file> 讀取設定、權限與受信任的 hook 根目錄，
                         取代 ~/.candy-code/config.json。亦
                         接受 --config=<file>。檔案必須已存在、
                         可讀、由你擁有，且檔案及其
                         目錄皆不可為全域可寫——它承載
                         權限政策，因此適用與 ~/.candy-code/config.json
                         相同的標準（/etc 或
                         /tmp 下的檔案通常會因上述原因之一被拒絕）。
                         僅該檔案會移動：代理、技能、工作流程、
                         工作階段與記憶仍留在 ~/.candy-code。
      --model <name>     以 <name> 作為對話模型，覆寫
                         $CANDY_CODE_MODEL 及供應商的預設值。亦
                         接受 --model=<name>。選取的是模型，非供應商
                         ——供應商仍取自 $CANDY_CODE_PROVIDER 或
                         已儲存的 `provider` 設定，兩者為
                         獨立軸線。
      --permission-mode <mode>
                         以 <mode> 執行，取代設定檔中的模式。
                         亦接受 --permission-mode=<mode>。最高
                         優先級：勝過 $CANDY_CODE_PERMISSION_MODE 與
                         permissionMode 設定鍵。可選值：default、
                         accept-edits、plan、auto、dont-ask、
                         bypass-permissions。皆未設定時，TUI 與 -p
                         以 default 啟動（寫入與 shell
                         命令前會先詢問）；僅本機啟動的 daemon 以
                         bypass-permissions 啟動。
      --max-cost <usd>   將本次啟動限制在 <usd> 美元的上報
                         消費：會超出上限的那一回合將被
                         拒絕且不會送出。亦接受 --max-cost=<usd>。
                         最高優先級：勝過 $CANDY_CODE_MAX_COST 與
                         maxCostUsd 設定鍵。允許小數，
                         接受 $ 前綴（$2.50）；零與負數
                         會被拒絕，而非解讀為「無上限」。/budget 仍可
                         提高或清除執行中工作階段的上限。
      --max-turns <n>    將本次啟動限制在 <n> 個工具迴圈步驟：
                         用完所有步驟的那一回合會就地停止並說明。
                         亦接受 --max-turns=<n>。最高優先級：
                         勝過 maxToolSteps 設定鍵（此軸線
                         無環境變數）。正整數；零
                         會被拒絕，而非解讀為「無
                         上限」，不可用的值會拒絕啟動
                         而非靜默退回設定值。
      --json-schema <path-or-json>
                         以 JSON Schema 約束回答：內嵌的
                         {"type":"object",...} 文件，或指向包含該文件的
                         路徑。亦接受 --json-schema=<value>；
                         當路徑以 "-" 開頭時應使用 = 形式。
                         僅回報支援 Schema 約束回答的供應商
                         才會執行該請求
                         ——其餘一律以退出碼 2 拒絕，而非
                         計費一個未約束的回答。Schema
                         僅約束該回合的自我完成請求；繼續
                         工具迴圈的步驟不受限（強制
                         JSON 回答無法攜帶工具呼叫）。
      --append-system-prompt <text-or-@file>
                         將操作者規則附加至本次啟動的系統
                         提示：內嵌文字，或 @path 指向包含規則的
                         檔案。亦接受 --append-system-prompt=<value>；
                         當路徑以 "-" 開頭時應使用 = 形式
                         以 "-" 結尾。規則會以另一個圍欄式
                         個人指令區塊傳入，絕非覆寫：它們
                         無法取代或降級其上各層，且
                         文字中偽造的區塊標記會被中和。
                         大小上限與指令文件相同。
                         僅搭配 -p 或 run 子命令：啟動時若無
                         可附加的提示詞，則以 exit 2 拒絕，而非
                         靜默忽略你提供的規則。
  -c, --continue         重新開啟最近使用的會話，包含記錄
                         在內的一切，而非建立新的。未使用時
                         每次啟動都開啟新會話；在空白
                         輸入框中按 Up 仍可呼叫先前的提示詞。
      --resume [<id|name>]
                         以 id、唯一 id 前綴或名稱重新開啟
                         已儲存的會話（見 `session list`）。未指定值時開啟
                         會話選擇器；搭配 -p 時目標為
                         必要（記錄會初始化單次執行，且
                         回覆會存回該列）。也接受
                         --resume=<id>。不可與 --continue 併用。
      --worktree [<name>]
                         在 git worktree 內執行整個會話，
                         名為 main-<name>、位於 candy-code/<name> 分支，
                         首次使用時建立；未指定名稱時自動命名。
                         結束時，若 worktree 無
                         提交且無修改則自動移除；有
                         工作則保留並顯示路徑。在
                         git work tree 外或搭配 `serve` 時拒絕。
      --incognito        不留存任何資料的啟動：無會話列、無
                         記錄、回合結束時不自動寫入記憶。
                         執行產出僅存在於程序中；
                         先前已儲存的會話與筆記仍可讀取。
                         搭配 --continue 或 --resume 時拒絕，
                         因為它們會重新開啟已儲存的會話。
      --restricted       無法執行程式碼的啟動：Bash、PtyRun、Task、
                         Workflow、ShellStop 與 mcp_call 從
                         整個會話的所有模型工具集中移除，且
                         /permissions 無法恢復。檔案工具保留，
                         仍受既有路徑限制。也接受
                         --restricted=true|false，讓外層腳本可覆寫
                         帶有裸旗標的別名。重新啟動後仍生效。
      --safe-mode        忽略所有信任的啟動：每個受信任的
                         專案根目錄視為不受信任（hooks、專案
                         MCP 與命令 shell），不載入 bundles，且
                         不探索外部 skills、commands 或 agents。
                         原生設定、skills 與 commands 保留。也接受
                         --safe-mode=true|false 以覆寫
                         別名。重新啟動後仍生效。
  -h, --help             顯示此說明訊息
  -v, --version          顯示已安裝版本後結束
      --                 選項結束：其後所有引數皆為位置參數，
                         絕非旗標

環境變數：
   CANDY_CODE_PROVIDER    使用的供應商：openai、anthropic、claude-code、
                          sglang、bedrock、vertex、custom
   CANDY_CODE_MODEL       模型名稱（覆寫供應商預設值；--model 優先）
   CANDY_CODE_PERMISSION_MODE
                          啟動時的權限模式，覆寫
                          permissionMode 設定鍵（--permission-mode 優先）
   CANDY_CODE_BACKEND_CMD 自訂後端適配器的 shell 命令，遵循
                          PROSE 契約：從 stdin 接收 JSON 歷史，將
                          回覆文字寫入 stdout，原樣使用
                          （僅修剪兩端空白，因此每個換行、空
                          行與內部縮排均保留）。
   CANDY_CODE_BACKEND_CMD_STREAM
                          同樣的 shell 呼叫，但遵循另一契約：TOKEN
                          串流：每行一個 token，兩 token 間的換行
                          為框架符號並被丟棄，空行則為
                          回覆中的字面換行。回呼每產生一個
                          token 觸發一次，但讀取迴圈為同步，
                          因此畫面在結束時重繪一次，
                          而非逐 token 更新。不可與
                          CANDY_CODE_BACKEND_CMD 互換——將 prose
                          包裝腳本透過此變數執行，回傳時所有
                          換行消失，每個空行收縮為一個。
                          兩者皆設定時 CANDY_CODE_BACKEND_CMD 優先。
                          兩者皆然：未設定、空值與純空白均視為
                          不存在。
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          嚴格逐一執行回合中的工具呼叫。
                          並行派遣為預設行為，且僅
                          分組非變更性工具；此為逃生口。
                          在
                          ~/.candy-code/config.json 中持久化為 "parallelToolCalls": false。
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          一個並行群組可執行的秒數，逾時後
                          落後者將被終止並回報為失敗呼叫
                          （預設 90，必須為 1-119；小數截斷）。
                          持久化為 "parallelToolDeadlineSeconds"。
                          優先順序：此變數，接著持久化鍵，
                          則使用預設值。超出 1-119 範圍的值，或
                          完全不是數字的值，不視為已設定——它
                          會繼續往下尋找下一個來源，而非
                          直接捨棄。
   CANDY_CODE_ADVISOR_MODEL
                          `Advisor` 工具諮詢的第二
                          觀點模型：無工具的補全，計費方式與
                          其他呼叫相同。與 CANDY_CODE_TITLE_MODEL 不同，
                          沒有廉價備援——未設定表示該工具
                          完全不提供。於啟動時讀取。
   CANDY_CODE_TITLE_MODEL 用於在工作階段首次對話後自動命名的廉價模型；
                          預設使用供應商的模型。
   CANDY_CODE_SUMMARY_MODEL
                          撰寫壓縮摘要的模型；
                          預設使用對話本身的模型，以重複利用
                          提示快取。
   CANDY_CODE_CONTEXT_PRUNING
                          auto、manual 或 off：工作階段如何修剪其
                          上下文（當 /pruning 未選擇時，預設 auto）。
   CANDY_CODE_MAX_COST    本次啟動的花費上限，以美元計
                          （允許小數；可接受前導 "$"；
                          --max-cost 優先）。超過上限的回合
                          將被拒絕。
   CANDY_CODE_CONNECT_TIMEOUT
                          連線階段上限，以秒計（允許小數；
                          預設 15.0），適用於供應商 HTTP
                          傳輸。僅限制建立連線
                          的時間——並非整體請求逾時。已連線的串流
                          伺服器發送其
                          回應標頭所需的時間，由獨立的
                          streamHeaderTimeoutSeconds 設定控制。
   CANDY_CODE_SEARCH_ENDPOINT
                          內建 WebSearch 工具查詢的搜尋 API。
   CANDY_CODE_SESSION_RETENTION_DAYS
                          正整數天數：每次啟動會刪除
                          至少該時長未使用的舊工作階段。
   CANDY_CODE_SHARE_UPLOAD_URL
                          已廢止的上傳主機：/share 從不上傳
                          任何地方。設定後，本機匯出仍會產生
                          且回覆會明確拒絕該金鑰並指出
                          /share serve，該指令會在你自己的
                          candy-code serve 上發布自架快照頁面。
   CANDY_CODE_WORKTREES_DIR
                          各隊友 git 工作樹建立的
                          基礎目錄。
   CANDY_CODE_DISABLE_MOUSE
                          任何非空且非 0 的值會完全關閉滑鼠
                          追蹤。
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          任何非空且非 0 的值會忽略點擊
                          手勢，但保留滾輪捲動。
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          任何非空且非 0 的值會關閉供應商的
                          提示快取斷點。
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          任何非空且非 0 的值會停止每回合後的
                          灰色下一則訊息建議（→ 接受）。
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          任何非空且非 0 的值會停止自動記憶
                          在回合後將持久事實儲存為筆記，以及
                          夢境處理將壓縮日誌整合
                          至其中的動作。
   CANDY_CODE_DISABLE_MODEL_METADATA
                          任何非空且非 0 的值會停止讀取與
                          更新 LiteLLM 模型資料庫（用於估算無內建
                          數值的模型大小與價格）。
   CANDY_CODE_NO_UPDATE_CHECK
                          任何非空且非 0 的值會停止每日 phar
                          發行檢查及其提供的啟動更新通知；
                          不會發出任何請求，且過期的快取
                          通知也不再顯示。
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          任何非空且非 0 的值會將排名
                          符號映射從系統提示中移除。
   CANDY_CODE_BACKGROUND  light 或 dark——強制自適應主題
                          對終端機背景的判斷，跳過
                          OSC 11 探測與 COLORFGBG。
   CANDY_CODE_DEBUG_SKILLS
                          任何非空且非 0 的值會將 SkillLoader 的
                          逐項跳過與逐項拒絕目錄的訊息重新輸出至
                          stderr。
   CANDY_CODE_DEBUG_COMMANDS
                          任何非空且非 0 的值會將 CommandLoader 的
                          探索拒絕訊息重新輸出至 stderr。
   CANDY_CODE_DEBUG_RULES 任何非空且非 0 的值會將 RuleLoader 的
                          探索拒絕訊息重新輸出至 stderr。
   CANDY_CODE_DEBUG_STREAM
                          任何非空且非 0 的值會保留 Chat 的
                          "onToken observer threw" 訊息於 stderr。
                          無論如何，分離本身仍會執行。
   CANDY_CODE_SERVER_HOST `serve` 綁定的位址（--host 優先）。
   CANDY_CODE_SERVER_PORT `serve` 綁定的埠號（--port 優先）。
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          以逗號分隔的額外來源，`serve` 會接受
                          （--allowed-origin 優先）。
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          以逗號分隔的額外主機名稱，`serve` 會回應
                          （--allowed-host 優先）。
   CANDY_CODE_SERVER_ALLOWED_IPS
                          以逗號分隔的用戶端 IP 或 CIDR，`serve` 會允許
                          迴環位址以外的（--allowed-ips 優先）。
   CANDY_CODE_SERVER_WEB_ROOT
                          `serve` 提供 Web UI 的目錄（--web-root
                          優先）。
   CANDY_CODE_SERVER_TOKEN
                          `serve` 要求的權杖，取代其狀態目錄中的
                          預設權杖（至少 32 字元；用於
                          容器環境）。
   CANDY_CODE_SERVER_DIR  `serve` 存放權杖、鎖檔、
                          探索記錄與日誌的目錄（預設
                          ~/.candy-code/server；建立時權限 0700）。
   CANDY_CODE_SERVER_PARENT_PID
                          `serve` 會隨此程序一同停止（--parent-pid 優先）。
   CANDY_CODE_MCP_DISABLE
                          設為 1、true 或 yes（不分大小寫）即完全靜音專案
                          MCP：.mcp.json 視為不存在，不啟動任何
                          伺服器。未設定、0 或其他值則保持
                          MCP 啟用——與旗標式變數不同，
                          僅這三個值有效。
   CANDY_CODE_QUIET_LOGS  設為 1、true 或 yes（不分大小寫）即靜音
                          error_log() 側通道為程序層級，僅有一處
                          輸出端；未設定、0 或其他值則保持
                          診斷輸出。僅啟動時讀取，無對應設定鍵。
   CANDY_CODE_REDUCED_MOTION
                          設為 1、true 或 yes（不分大小寫）將代理
                          轉圈動畫固定為單一靜態畫面——供對動態敏感
                          及偏好減少動態的使用者。僅啟動時讀取一次；
                          無對應設定鍵。
   CANDY_CODE_SD_BASE_URL A1111 風格（sdapi）Stable
                          Diffusion 伺服器的基礎 URL，供媒體傳輸層連線。
                          優先順序：程式碼明確覆寫，接著此
                          變數，最後是 sd.baseUrl 設定。
   CANDY_CODE_MEDIA_RENDER_MODE
                          終端機中生成圖片的繪製方式
                          （ui.imageRenderMode 設定的環境變數層；參見
                          docs/ENVIRONMENT.md 取得可接受的值）。
   CANDY_CODE_ALLOW_ROOT_TESTS
                          設為 1 以允許 candy-code TEST SUITE
                          以 root 執行；未設定或其他值，測試套件
                          在 euid 0 時拒絕啟動。不影響
                          candy-code 的啟動行為——測試套件並非
                          面向使用者的介面。
   CANDY_CODE_TOOL_INPUT  目前使用者腳本工具呼叫的完整參數對應表，
                          以 JSON 編碼，匯出至每個 ~/.candy-code/tools
                          工具執行時產生的子程序中；
                          應用程式僅寫入、不讀回，且
                          使用者無需自行設定。
   CANDY_CODE_OTEL_BATCH_SIZE
                          每個 OTLP 匯出批次攜帶的 span 數量
                          （預設 64，限制在 1..2048）。
   CANDY_CODE_OTEL_TIMEOUT
                          每次 OTLP 匯出嘗試允許的秒數
                          （預設 3；非正值或格式錯誤的值
                          將回退至預設值）。

   docs/ENVIRONMENT.md 彙整此版本讀取的所有變數及其
   完整契約。

退出碼（單次模式與所有子命令）：
  0                      提示詞執行成功並產出回應，或子命令
                         正常完成
  1                      執行失敗：後端拋出錯誤（主機不可達、
                         金鑰被拒、模型錯誤）——重試可能有效——或
                         子命令執行失敗（doctor 檢查回報
                         FAIL、`session` 找不到對應工作階段、
                         已信任的 .mcp.json 無法解析）
  2                      用法或設定錯誤，未嘗試任何操作
                         且重試無效：未提供提示詞、
                         無法識別的旗標、未指向現有目錄的
                         裸參數（提示詞需搭配 -p）、--root
                         指向不存在的目錄、缺少 composer
                         autoload.php，或選定的供應商
                         無法建立——來自
                         $CANDY_CODE_PROVIDER 或持久化於
                         ~/.candy-code/config.json 中由 Ctrl+P "Switch model" 設定的供應商。
                         單次執行不會回退至離線 echo
                         供應商（當已明確選定供應商時）。
                         子命令收到缺少或未知的運算元
                         （`session`、`mcp bogus`、`completion tcsh`）回報
                         此退出碼。
  130/143/129             TUI：訊號停止了迴圈 — 128+N 對應
                         SIGINT (Ctrl+C)、SIGTERM、SIGHUP；協作式
                         退出 (/exit, q) 仍以 0 結束。

範例：
  candy-code -p "Explain the difference between require and include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Write a hello world in Go"
  candy-code run "Write a hello world in Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

更多資訊請參閱 README：
  https://github.com/detain/sugarcraft/tree/master/candy-code

TXT,
    'cli.keychain.empty_name' => '一個 ${keychain:} 參考未指向任何條目 — 解析為空字串。',
