    'cli.refuse.dangling_directory' => '{dir} 是一個符號連結，無法解析至此程序可搜尋的目錄',
    'cli.refuse.foreign_owner' => '{path} 屬於 uid {uid}，而非此工作階段執行的帳號，因此其權限政策與 hook 鏈屬於他人。拒絕啟動，而非以他人帳號的政策執行。',
    'cli.refuse.hook_chain' => '{error} 拒絕啟動，而非以非設定的 hook 鏈執行。',
    'cli.refuse.hooks_unreachable' => '{path} 無法存取：{reason}，因此無法得知該處是否設定了 hooks。拒絕啟動，而非以未知的 hook 鏈執行。',
    'cli.refuse.keybindings' => 'keybindings 設定無法使用：{reason}。移除該鍵以使用內建按鍵配置（/keys 參考文件列出了它們）。拒絕啟動，而非以您未取得的按鍵覆寫執行。',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST 為 \'{value}\'，不是有效的支出上限。預期為正數美元（允許小數，可加 $ 前綴），例如 5 或 $2.50。零與負數會被拒絕而非解讀為「無上限」，因為它們是相反的要求；無法表示的過大數值（1e309，即無限大）會被拒絕，因為它會安裝一個永不觸發的上限。取消設定該變數即為無上限。拒絕啟動，而非以您要求了上限卻無上限地執行。',
    'cli.refuse.max_cost_flag' => '--max-cost 為 \'{value}\'，不是有效的支出上限。預期為正數美元（允許小數，可加 $ 前綴），例如 5 或 $2.50。零與負數會被拒絕而非解讀為「無上限」，因為它們是相反的要求；無法表示的過大數值（1e309，即無限大）會被拒絕，因為它會安裝一個永不觸發的上限。移除該旗標即為無上限。拒絕啟動，而非以您要求了上限卻無上限地執行。',
    'cli.refuse.max_cost_setting' => '您的設定中 maxCostUsd 為 {value}，不是有效的支出上限。預期為正數美元，例如 5 或 2.5。移除該鍵即為無上限。拒絕啟動，而非以您要求了上限卻無上限地執行。',
    'cli.refuse.max_turns_flag' => '--max-turns 為 \'{value}\'，不是有效的步驟上限。預期為正整數的工具迴圈步驟數，例如 8。零會被拒絕而非解讀為「無上限」，因為它是相反的要求；無法表示的過大數值會被拒絕，因為它會安裝一個永不觸發的上限。移除該旗標以改用 maxToolSteps 設定。拒絕啟動，而非以您要求了上限卻無上限地執行。',
    'cli.refuse.no_home' => '此程序無法判斷您的家目錄（$HOME 未設定、$USERPROFILE 未設定，且其 uid 沒有 passwd 條目），因此無法定位 ~/.candy-code 中的權限政策與 hook 鏈。拒絕啟動，而非從全域可寫的備援目錄讀取它們——請將 HOME 匯出為此工作階段所屬帳號。',
    'cli.refuse.no_project_root' => '無法判斷專案根目錄——程序的工作目錄不可用（已刪除或不可讀）。請傳入 --root <dir>。',
    'cli.refuse.not_searchable' => '{dir} 無法被此程序搜尋',
    'cli.refuse.project_settings_unusable' => '無法讀取 {path} 的 permissionRules（{reason}）。拒絕啟動，而非以未知的權限政策執行。',
    'cli.refuse.world_writable' => '{path} 可被此機器上的所有帳號寫入，因此其權限政策與 hook 鏈不屬於此使用者。拒絕啟動，而非以任何人都可能寫入的政策執行——`chmod o-w {path}`。',
    'cli.selfupdate.channel_invalid' => '{value}：candy-code self-update --channel 僅接受 stable 或 dev。',
    'cli.selfupdate.check_available' => 'candy-code: 有更新可用——目前安裝版本為 {current}，最新發布版本為 {latest}。（--check 僅報告；未安裝任何內容。）',
    'cli.selfupdate.check_unknown' => 'candy-code: 無法比較目前安裝版本（{current}）與最新發布版本（{latest}）。',
    'cli.selfupdate.check_up_to_date' => 'candy-code: 已是最新——目前安裝版本為 {current}，最新發布版本為 {latest}。',
    'cli.selfupdate.composer_mode' => 'candy-code: self-update 會替換 phar 安裝，而此副本是透過 Composer 安裝的——這裡沒有 phar 可替換。請使用以下指令更新：{command}（全域安裝則執行 `composer global update sugarcraft/candy-code`）。',
    'cli.selfupdate.composer_mode_root' => 'candy-code: self-update 會替換 phar 安裝，而此副本是作為 Composer 根套件安裝的 sugarcraft/candy-code 套件——這裡沒有 phar 可替換，且根套件無法透過自身的依賴指令自我更新。請使用以下指令更新：{command}（該 clone 會拉取新原始碼，然後重建 vendor 目錄樹）。',
    'cli.selfupdate.dir_not_writable' => 'candy-code: 無法替換 phar——目錄 {dir} 不可寫入。',
    'cli.selfupdate.downgrade_refused' => 'candy-code: 拒絕降級——目前安裝版本為 {current}，最新發布版本為 {latest}。（--rollback 會還原保留的副本；其他內容不會回退。）',
    'cli.selfupdate.download_failed' => 'candy-code: 無法下載 {asset}：{reason}',
    'cli.selfupdate.empty_download' => 'candy-code: 下載 {asset} 未產生任何位元組。',
