    'cli.selfupdate.sig.deprecated' => 'candy-code: 此版本以 {asset} 對原始 phar 位元組進行簽章；該舊版流程會將整個產物讀入記憶體，並再接受一個發布週期。請發布 {replacement}——對 sha256 sidecar 內容的 Ed25519 簽章——使驗證全程在串流中完成。',
    'cli.selfupdate.sig.sidecar_invalid' => 'candy-code: {asset} 未能以固定的發布金鑰驗證下載的 {sidecar} sidecar（{phar}）。未替換任何內容。',
    'cli.selfupdate.signature_invalid' => 'candy-code: {asset} 未能以固定的發布金鑰驗證下載的 {phar}。未替換任何內容。',
    'cli.selfupdate.signature_missing' => 'candy-code: 此版本不含 {asset} 也不含 {sig_sidecar}，而固定的發布金鑰要求 {phar} 必須有其中之一。未替換任何內容（--allow-unsigned 僅供開發使用）。',
    'cli.selfupdate.staged_windows' => 'candy-code: 更新已暫存以等待重新啟動——{new} 將在此程序退出時替換至 {path}；進度記錄於 {path}.swap.log，保留的副本仍在 {old}。',
    'cli.selfupdate.swap_leftover' => 'candy-code: 先前的 self-update 在 {new} 留下了未套用的暫存替換（其 swap log 記錄了放棄的嘗試）。本次執行會在更新前取代該暫存。',
    'cli.selfupdate.swap_spawn_failed' => 'candy-code: 無法啟動替換輔助程序；已驗證的位元組暫存於 {new}，執行中的副本完好。請手動完成對 {path} 的重新命名，或在沒有程序佔用該檔案後重新執行 self-update。',
    'cli.selfupdate.uncomparable' => 'candy-code: 此安裝回報 {current}，不是 self-update 可處理的發布版本。',
