    'cmd.mcp-auth.login-armed' => "↻ 已為 `{server}` 啟動 MCP 登入 — 等待瀏覽器連結。\n\n子程序綁定迴環埠；在 TUI 保持回應的同時於瀏覽器中完成。此工作階段的 MCP 用戶端在啟動時已快取其儲存，因此權杖在下次啟動時生效；`/mcp list` 在憑證儲存後顯示它。",
