    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ `{server}` 的 MCP 登入以退出碼 {code} 結束，未儲存權杖。

子程序的最後幾行在上方；在 shell 中執行相同流程（`candy-code mcp auth login {server}`）會印出完整錯誤，是除錯端點或埠號問題的地方。
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ 無法啟動 `{server}` 的 MCP 登入子程序。\n\n直接執行 shell 形式：`candy-code mcp auth login {server}`。",
    'cmd.mcp-auth.login-guidance' => "互動式登入是 shell 命令，非對話輪次：\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\n此指令執行 OAuth 授權碼流程（含 PKCE）：你的瀏覽器\n會將授權碼回傳至 shell 中的 loopback 監聽器，儲存的\n權杖將於下次啟動時自動附加至匹配的 http 伺服器。",
    'cmd.mcp-auth.login-no-entry' => "✗ 找不到此程式自身的進入點以 fork `mcp auth login {server}`。\n\n請直接在 shell 中執行：`candy-code mcp auth login {server}`。",
    'cmd.mcp-auth.login-served-armed' => "↻ 已在 SERVER 主機上為 `{server}` 啟動 MCP 登入——連結將顯示於下方；請在你自己的瀏覽器中開啟。你的瀏覽器無法直接連線到伺服器的 loopback 監聽器：若瀏覽器顯示連線錯誤頁面，請複製該頁面的網址，並傳送 `/mcp login {server} --code <that-url>` 將回呼傳給等待中的登入。權杖將於下次啟動時附加；`/mcp list` 會在憑證儲存後顯示。",
    'cmd.mcp-auth.login-url' => '→ 開啟此網址以授權 `{server}`：\n\n  {url}',
