✓ 已成功註冊 `{server}`
Client ID：`{client}`
對具有此確切 URL 的 http MCP 伺服器之請求，現在會自動攜帶此權杖，到期前自動刷新；在此指令之前啟動的伺服器將於下次啟動時取得。
TXT,
