    // --- fix-tui-interact 2026-10-14 ---
    'tui.picker.notice.slash_filter' => '`{word}` 看起來像斜線命令而非篩選條件 — 在此按 Enter 會繼續最佳匹配。請按 Escape 並在輸入框中鍵入命令。',
