    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => '缺少 — 字元寬度計算（mb_*）無法執行；請重新安裝含 ext-mbstring 的 PHP',
    'appLaunch.doctor.intl_missing' => '缺少 — grapheme/IntlChar 寬度計算無法執行；請重新安裝含 ext-intl 的 PHP',
    'appLaunch.notice.policy_changed' => '⚠ config.json 或 hooks.yaml 自上次啟動後已變更。新的專案 hooks 僅在本次啟動中隔離 — 請檢視 ~/.candy-code/config.json 和 hooks.yaml，之後即會生效',
    'appLaunch.notice.project_policy_changed' => '⚠ 受信任專案的 hooks.yaml 含有上次啟動未見的新條目。新的專案 hooks 僅在本次啟動中隔離 — 請檢視該儲存庫的 .candy-code/hooks.yaml，之後即會生效',
    'appLaunch.notice.bypass_mode' => '⚠ 權限模式為 bypass-permissions：每個工具呼叫都無需提示即執行。請使用 /permissions（TUI）、--permission-mode 或在 ~/.candy-code/config.json 中設定其他權限模式來變更',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p 以預設權限模式啟動：無人值守執行會拒絕所有需要確認的工具呼叫。腳本執行請使用 --permission-mode（bypass-permissions 可執行全部）',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview 在本次啟動中預設開啟：被標記的 auto-mode 呼叫會由標題模型審查，每次審查都是付費模型呼叫。請在 ~/.candy-code/config.json 中將 autoReview 設為 false 以退出',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} 縮小了本次啟動的權限：先載入 {count} 條 deny/ask 規則，{dropped} 條 allow 規則已捨棄 — 專案檔案無法授予 allow',
    'appLaunch.notice.restricted' => '⚠ --restricted：本次啟動不含任何程式碼執行工具 — Bash、PtyRun、Task、Workflow、ShellStop 和 mcp_call 已從所有模型可見的集合中移除；檔案工具仍受路徑限制，且 /permissions 無法將已移除的工具加回',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode：本次啟動忽略所有受信任的專案根目錄、bundles 以及外部 skills、commands 和 agents — 行為如同從未信任過任何內容',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => '未設定任何供應商，因此本次工作階段使用內建離線 echo 後端 — 回覆僅在本地回顯，不會呼叫模型。請執行 `candy-code doctor` 查看供應商所需設定，設定完成後按 Ctrl+P 切換模型。',
    'keys.chat.repaint' => '清除畫面並重繪框架',
    'keys.unbound' => '未綁定',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ `async` Claude Code hook `{hook}` 以 {code} 退出。`async` hook 僅要求監看工具呼叫而非攔截，因此無權阻擋，呼叫已繼續執行。其輸出：{reason}',
    'hooks.notice.claude_dialect' => '⚠ Claude Code hook `{hook}` 以 {code} 退出，Claude Code 將其視為非阻擋性抱怨而非決定，因此工具呼叫已繼續執行。其輸出：{reason}',
    'hooks.notice.said_nothing' => '（stderr 無輸出）',
    'hooks.notice.system_message' => '⚠ 鉤子 `{hook}` 留了一則訊息給你：{message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'HTTP 鉤子 `{hook}` 設定了一個無法使用的 URL（{reason}）；顯示的目標為 {target}。一個無法說明其去向的鉤子，未核准此呼叫。',
    'hooks.http.deny_scheme' => 'HTTP 鉤子 `{hook}` 指定了 {target}，這不是 http 或 https URL。candy-code 僅透過這兩種協定撥接鉤子，因此拒絕此呼叫，而非對未經審核的傳輸層執行。',
    'hooks.http.deny_credentials' => 'HTTP 鉤子 `{hook}` 在 URL 中攜帶了憑證（{target}）。寫入 URL 的密碼會洩漏到日誌與代理中，因此在此拒絕；請改為以標頭傳送，其值讀取 `allowedEnvVars` 名稱。',
    'hooks.http.deny_blocked_target' => 'HTTP 鉤子 `{hook}` 無法被諮詢：{reason}（{target}）。私有與連結本地位址受到與出站抓取相同的規則拒絕，而從未觸及的守衛未核准此呼叫。',
    'hooks.http.deny_unanswered' => 'HTTP 鉤子 `{hook}` 未回應（{reason}）；目標為 {target}。無法連達的鉤子未核准此呼叫，因此拒絕。',
    'hooks.http.deny_header_injection' => 'HTTP 鉤子 `{hook}` 無法傳送其 `{field}` 標頭：名稱或值含有控制字元，屬於請求框構而非標頭值。未向 {target} 傳送任何內容，呼叫已拒絕。',
    'hooks.http.notice_unanswered' => '⚠ HTTP 鉤子 `{hook}` 未回應（{reason}），因此無法把關此呼叫。詢問目標為 {target}。',
    'hooks.http.reason_unreachable' => '連線或請求在其自身的鉤子逾時內逾時',
    'hooks.http.reason_oversized' => '回應超過 {bytes} 位元組且未正常結束',
    'hooks.http.reason_no_status' => '回覆未包含 HTTP 狀態列',
    'hooks.http.reason_redirect' => '它發出了重導向，而鉤子呼叫不跟隨重導向',
    'hooks.http.reason_status' => '回覆不是 2xx 狀態碼',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => '提示鉤子 `{hook}` 未回應（{reason}）。從未回傳裁決的鉤子未核准此呼叫，因此拒絕。',
    'hooks.prompt.notice_unanswered' => '⚠ 提示鉤子 `{hook}` 未回應（{reason}），因此無法把關此呼叫。',
    'hooks.prompt.reason_call_failed' => '無法詢問模型',
    'hooks.prompt.reason_empty_verdict' => '提示鉤子 `{hook}` 拒絕了此呼叫，且未給出理由。',
    'hooks.prompt.reason_no_backend' => '此啟動沒有標題模型後端可供詢問',
    'hooks.prompt.reason_no_prompt' => '該條目的提示為空，無可詢問',
    'hooks.prompt.reason_unparseable' => '其回覆不是要求必須回傳的單一 JSON 物件（含布林值 `ok`）',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => '`Advisor` 工具諮詢以取得第二意見的模型；未設定（預設值）時完全不提供該工具（無廉價模型備援：重點是你選定的模型）。',
    'settings.allowedTools.help' => '工具名稱或 glob 的白名單；未設定時提供所有工具。',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}：git 指引所要求的尾註與 PR 行。',
    'settings.autoCommit.help' => 'off、turn（每輪一次提交，訊息取自標題模型）或 edit（每次 Write/Edit 一次）；/undo 可復原。',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => '在 auto 模式下，安全分類器標記的呼叫（安全發現除外，其一律詢問）由標題模型審核，模型可允許、詢問你或拒絕。只要存在可審核的模型即預設開啟，啟用此預設的啟動會告知一次；設為 false 可退出。每次審核都是一次付費模型呼叫。',
    'settings.autoReviewModel.help' => 'auto 審核器執行的 `provider/model`，例如 `openai/gpt-4.1-mini`；空白表示使用標題模型。無法建立的 provider 會關閉審核器並發出啟動警告。',
    'settings.autoReviewScope.help' => '`autoReview` 送給審核器的內容：`shell`（預設）為模式清單通過的所有非唯讀 shell 命令；`writes`  additionally 審核 `Edit`、`Write`、`ApplyPatch` 和 `WebFetch`，寫入工具附帶待處理 diff；`all` 審核清單通過的所有呼叫。其他拼寫行為等同 `shell`。每次審核都是一次付費模型呼叫。',
    'settings.autoTest.help' => '編輯檔案後的輪次結束時執行 `testCommand`；失敗時輸出回傳給模型，每輪最多 3 次。',
    'settings.bashInteractiveIdleSeconds.help' => '`interactive: true` 的 Bash 執行可無輸出多久後被視為等待按鍵而停止（秒）。',
    'settings.bashMaxTimeoutSeconds.help' => 'Bash 命令可請求的最大 `timeout`；超過的值會被鉗制至此上限。',
    'settings.bashSandbox.help' => 'Linux 在 bubblewrap 內執行 Bash；macOS 透過 `sandbox-exec` 在 Seatbelt 設定檔內執行——僅工作根目錄可寫（`no-network` 同時切斷網路）。`allowlist`（Linux）將網路出站路由至啟動的出站代理，僅允許 `sandboxAllowedDomains` 中列出的主機：預設 EMPTY 清單下行為完全等同 `no-network`，直到你列出主機；即使列出，非 HTTP 流量（ssh、資料庫埠）及未列出的主機仍會失敗。macOS 上 `allowlist` 以 `no-network` 執行。無法啟動監獄時拒絕命令；無法辨識的值等同 `no-network`，絕非 `off`。',
    'settings.bashSandboxNestedUserns.help' => '設為 `true` 允許沙箱化的 `Bash` 命令建立自己的使用者命名空間，rootless podman、buildah 及 Chromium 沙箱需要此功能。預設 `false` 以 `--unshare-user --disable-userns` 執行 bubblewrap，阻擋從掛載監獄逃出的常見路徑；若主機的 bubblewrap 太舊不支援這些旗標，監獄以基本集合執行，其自身描述會說明。',
    'settings.bashTimeoutSeconds.help' => '模型未傳 `timeout` 時 Bash 命令可執行的秒數；絕不超過 Bash 上限。',
    'settings.chatToolTimeoutSeconds.help' => 'chat-native（`command` provider）路徑分叉的一批工具呼叫的牆鐘預算；落後者會被終止。',
    'settings.claudeMcpArgs.help' => '該二進位檔的引數；未設定時使用傳輸層預設值。',
    'settings.claudeMcpBinary.help' => 'claude-mcp 傳輸層可衍生的 `claude` 二進位檔絕對路徑。',
    'settings.claudeMcpEnv.help' => '直接傳給該二進位檔的字面環境變數。',
    'settings.compaction.autoPercent.help' => '較舊的交換在提示送出前自動壓縮的視窗佔比。',
    'settings.compaction.autoTokens.help' => '自動層與輪內步驟預算的絕對上限。0 表示關閉上限。',
    'settings.compaction.blockPercent.help' => '超過此視窗佔比時拒絕提示直到釋放空間；唯一會拒絕的層。',
    'settings.compaction.blockTokens.help' => '阻擋層的絕對上限；預設未設定。設定後上限可拒絕提示。',
    'settings.compaction.idleAuto.help' => '在空閒期間壓縮超過層級的閒置工作階段，而非等待下一個提示，使用自動層的機制（花費上限與抖動斷路器適用）。off：永不壓縮；hour：經過完整的 compaction.idleOfferSeconds 視窗後；cacheTtl：略早於 provider 的提示快取過期——provider 標記快取斷點時為一小時，server-side 快取約 5 分鐘，回報無快取時永不壓縮——歷史超過自動層下限一個 floor 時壓縮，否則下一個提示會以未快取方式預填整個對話；在 60 秒 tick 上，5 分鐘快取約在 4 分鐘閒置時折疊。會產生一次背景 provider 呼叫；需要 compaction.idleOfferSeconds 大於 0。布林值仍可讀取：true 等同 hour，false 等同 off。',
    'settings.compaction.idleOfferSeconds.help' => '超過整個上下文視窗且閒置此時間的工作階段，會提供 /compact 而非送出提示。0 表示永不提供。',
    'settings.compaction.keepRecent.help' => '壓縮時完整保留的最近使用者/助理交換數。',
    'settings.compaction.mode.help' => 'llm：摘要模型撰寫摘要（啟發式為其備援）；heuristic：本地單行摘要，絕不呼叫模型；off：不自行壓縮，/compact 仍可用，阻擋層仍會拒絕。',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" 或 "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} 覆寫三個上限；0 清除其中一個。',
    'settings.compaction.refillLimit.help' => '連續自動壓縮次數，其結果可能立即再次超過層級（提示未送出），之後下一個提示被拒絕而非再次壓縮。',
    'settings.compaction.reminderPercent.help' => '「考慮壓縮」提醒與提前背景摘要開始的視窗佔比；低於自動層。',
    'settings.compaction.reminderTokens.help' => '提醒層的絕對上限：以 min(百分比, 此值) 觸發。0 表示關閉上限。',
    'settings.compaction.summaryAssistantChars.help' => '超過此長度的助理回覆在啟發式摘要行中變為「[已交換資訊]」。',
    'settings.compaction.summaryUserChars.help' => '啟發式摘要行保留的使用者訊息字元數。',
    'settings.compaction.toolOutputChars.help' => '摘要模型看到的已壓縮交換中助理部分的字元數。',
    'settings.connectTimeoutSeconds.help' => '抵達 provider 主機的期限（DNS、TCP、TLS）；非請求逾時。',
    'settings.contextPruning.compress.help' => 'manual 僅在你以 /compress 啟動的輪次提供 Compress，一次呼叫；auto 在模型可能修剪的每個輪次提供。',
    'settings.contextPruning.iterationNudgeThreshold.help' => '自上一個提示以來的工具結果數，超過後長工具迴圈會收到修剪提醒。',
    'settings.contextPruning.maxContextTokens.help' => '超過此上下文大小時，最新列攜帶較強的「立即修剪」提醒。',
    'settings.contextPruning.minContextTokens.help' => '低於此上下文大小時永不提醒模型修剪；不得超過硬性提醒大小。',
    'settings.contextPruning.mode.help' => 'auto 在每輪開始時修剪已取代的列；manual 僅在 /sweep 時；off 不顯示 ref 標籤。/pruning 可逐工作階段覆寫。',
    'settings.contextPruning.nudgeFrequency.help' => '提醒在上一個提醒後需等待的新列數，避免每步重複。',
    'settings.contextWindow.help' => 'Token 視窗覆寫：provider 模型的數量，或 {"<model>": tokens}。',
    'settings.debug.commands.help' => '將每個被拒絕的自訂命令目錄或檔案輸出到 stderr，而非僅啟動時的一行計數。',
    'settings.debug.rules.help' => '將每個被拒絕的規則目錄或檔案輸出到 stderr。',
    'settings.debug.skills.help' => '將每個跳過的技能檔案和被拒絕的技能目錄輸出到 stderr，而非僅啟動時的一行計數。',
    'settings.debug.stream.help' => '當嵌入方的串流接收器在輪中失敗時，將「onToken 觀察者拋出異常，已分離」這行輸出到 stderr。',
    'settings.diffPreviewRows.help' => 'Edit 或 Write diff 在摘要其餘部分前於記錄中顯示的行數。',
    'settings.diffStyle.help' => '記錄中的 diff 版面：`auto` 在寬終端機（120 欄以上）並排顯示區塊，其餘使用統一格式；`unified` 永遠單欄；`split` 永遠雙欄。兩種版面中 diff 主體依 token 著色；`+`/`-` 標記欄保持其顏色。',
    'settings.disabledMcpServers.help' => '`.mcp.json` 中永不啟動、列出或呼叫的伺服器名稱或 glob（`untrusted_*`），適用於主代理及所有子代理。',
    'settings.disabledRules.help' => '從第一輪起排除在提示外的使用者層規則包。',
    'settings.disabledSkills.help' => '從探索中移除的技能；也優先於 enabledSkills。',
    'settings.disabledTools.help' => '從模型可見工具集中移除的工具名稱或 glob。',
    'settings.doubleEscSeconds.help' => '第二次 Esc 必須在多短時間內跟隨第一次以取消執行中的輪次。',
    'settings.embeddingModel.help' => '每輪記憶召回的嵌入模型；未設定時僅以關鍵字排序筆記。',
    'settings.enabledSkills.help' => '每輪將完整內容附於系統提示的技能。',
    'settings.env.diffMaxBytes.help' => '兩個 git diff 區塊各自在截斷並附註前保留的位元組數。',
    'settings.env.gitDiffAfterWrites.help' => '寫入檔案的步驟後，在輪次上下文中顯示已暫存與未暫存的 git diff。',
    'settings.expandToolOutput.help' => '在記錄中完整顯示每個已完成工具呼叫的輸出；Ctrl+O 或點擊仍可折疊單個。',
    'settings.extraBody.help' => '附加到每個 `custom` provider 請求的頂層請求欄位。',
    'settings.formatCommands.help' => '依檔案副檔名的編輯後格式化命令（{"php": "vendor/bin/php-cs-fixer fix {file}"}）；在編輯後 lint 之前執行並重寫檔案。預設關閉。',
    'settings.formatAuto.help' => '讓內建副檔名表（gofmt、rustfmt、ruff/black、shfmt、terraform fmt、專案自身的 node_modules prettier）在 `formatCommands` 未為該副檔名指定命令時格式化已編輯檔案。明確條目優先；專案仍需 `trustedProjectHooks`。預設關閉。',
    'settings.globMaxMatches.help' => '單一 Glob 在停止走訪前收集的路徑數；輸出上限仍約束結果。',
    'settings.grepTimeoutSeconds.help' => '單一 Grep 搜尋在被終止前可執行的秒數；截止前找到的命中以部分結果回傳。',
    'settings.hooksDefaultTimeoutSeconds.help' => '未指定 `timeout:` 的鉤子條目在被終止並計為拒絕前可執行的秒數。',
    'settings.includeGitInstructions.help' => 'Bash 工具的通用提交指引是否附於系統提示。',
    'settings.instructions.help' => '其內容成為權威系統提示文字的檔案 glob。',
    'settings.instructions.walkToRoot.help' => '選擇加入：也讀取最近 .git 標記之上的指令檔案，直到但不包含家目錄。僅使用者層；每次讀取仍受包含與大小預算約束。',
    'settings.instructionsExclude.help' => '要跳過的指令檔案 glob，記錄為拒絕；僅使用者層——儲存庫無法靜音其操作者。簽出內的檔案以簽出相對路徑匹配；祖先與強制的外部檔案以絕對路徑匹配，因此 `**/CLAUDE.local.md` 也能觸及祖先副本。',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}：將額外的按鍵組合綁定到綁定 ID（/keys 參考文件列出名稱）——Ctrl+<key>、Alt+<key>、Shift+<key> 或單獨的功能鍵；出廠按鍵組合仍有效。存在但不可用會拒絕啟動；移除該鍵以恢復出廠綁定。',
    'settings.layout.help' => '停靠面板清單；面板移動時由 shell 寫入。',
    'settings.lintCommands.help' => '依檔案副檔名的編輯後 lint 命令（{"php": "…", "js": false}）；`php -l` 為內建。',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}：用於編輯後診斷、Read 大綱及 Lsp 工具的伺服器。',
    'settings.lspAutoDetect.help' => '啟動專案指紋所命名的語言伺服器（composer.json → intelephense、package.json + tsconfig.json → typescript-language-server、pyproject.toml 或 setup.py → pyright-langserver、go.mod → gopls、Cargo.toml → rust-analyzer），前提是其執行檔位於 PATH 中；手動 `lsp` 條目在各語言中優先。啟動伺服器會執行該伺服器及已開啟目錄樹中的建置程式碼，因此指紋僅在你已信任 hooks 的專案中啟動伺服器；未信任的根目錄不啟動任何伺服器，並在啟動通知中記錄跳過。',
    'settings.maxCheckpoints.help' => '每個工作階段中 /rewind 可回溯的回合檢查點數量；超過此上限時最舊的將被清除。',
    'settings.maxCostUsd.help' => '啟動的供應商回報花費達到此美元數時，拒絕新回合；未設定則無上限。/budget 僅變更目前執行中啟動的設定。',
    'settings.maxOutputTokens.help' => '每次請求的輸出上限；未設定時不傳送覆蓋值，使用供應商預設值。',
    'settings.maxToolSteps.help' => '單輪可進行的供應商呼叫次數；未設定則使用引擎預設值。',
    'settings.mcp.enabled.help' => '啟動受信任專案 .mcp.json 中指定的 MCP 伺服器；off 則不啟動任何伺服器，且各介面將啟動狀態回報為已停用。',
    'settings.mcp.lazySchemaTokens.help' => '單一 MCP 伺服器在其工具延後至 mcp_list/mcp_call 前可宣告的 Schema 權杖數；0 表示永不延後。',
    'settings.mcpResultCapBytes.help' => '單一 MCP 工具回覆可傳給模型的最大位元組數。',
    'settings.memory.autoConsolidate.help' => '將已完成回合中的持久事實存入記憶，並把壓縮日誌併入其中（夢境處理）；每次皆為計費呼叫。',
    'settings.memory.dreamIntervalSeconds.help' => '同一專案兩次 dream pass 之間的最短時間；每次 pass 為計費的唯讀回合。',
    'settings.memory.dreamProposeSkills.help' => '讓 dream pass 以草稿形式提出技能至 ~/.candy-code/skills-proposed；在你以 /skills 接受之前，皆不會生效。',
    'settings.memory.entryMaxBytes.help' => '最長單筆筆記的索引行可能在截斷顯示前出現；若超出使用者筆記預算則降至預算內。',
    'settings.memory.projectNoteMaxBytes.help' => '單一專案記憶筆記寫入儲存庫 .candy-code/memory/ 時的最大容量。',
    'settings.memory.promptMaxBytes.help' => '記憶索引註記行的位元組預算；使用者註記預算會調低以符合該上限。',
    'settings.memory.promptMaxEntries.help' => '提示詞記憶索引所列最多筆記，最新在前；使用者筆記計入其中。',
    'settings.memory.userMaxBytes.help' => '使用者範圍行的位元組預算（總預算內）。',
    'settings.memory.userMaxEntries.help' => '您的跨專案（使用者範圍）筆記大多排在最前面，於筆記計數內顯示。',
    'settings.modelPrices.help' => '每個模型每 1M token 的 USD 單價（{"input": …, "output": …}），用於支出總額與上限',
    'settings.models.help' => '各供應商要執行的模型（{"<provider>": "<model id>"}）；未設定則使用供應商預設值。',
    'settings.mouse.help' => '將滑鼠事件回報給 candy-code（點擊、滾輪、選取）；停用後終端機恢復自身的選取即複製功能。',
    'settings.mouseClicks.help' => '點擊與拖曳對所觸碰的物件生效；關閉時保留滾輪並忽略點擊。',
    'settings.notices.transcriptLimit.help' => '多數啟動警告以記錄列呈現；其餘歸入一行「還有 N 則」，stderr 則包含全部。',
    'settings.notify.help' => 'off、bell (BEL) 或 osc9（桌面通知）：回合結束及代理等待核准時發送。',
    'settings.paletteMru.help' => '記憶最近使用的調色盤列數並排在最前面；0 表示不記憶。',
    'settings.parallelToolCalls.help' => '並行執行單輪唯讀工具呼叫。',
    'settings.parallelToolDeadlineSeconds.help' => '單批併發工具呼叫的實際時間上限。',
    'settings.permissionMode.help' => '工具呼叫的門控方式。絕不從專案檔案取得。',
    'settings.permissionRules.help' => '依序排列的 allow / deny / ask 規則，與每次工具呼叫逐一比對。受信任專案共用的 settings.json 可加入 deny / ask 條目——僅限縮權限。',
    'settings.permissions.autoAllowReadOnly.help' => '在 default 與 accept-edits 模式下，直接執行僅含唯讀命令（ls、cat、grep、git log、…；無檔案重導向、無命令替換、cd 僅限專案內）的 Bash 指令行，無需詢問。專案僅可關閉此功能。',
    'settings.permissions.autoStrikeLimit.help' => '在 auto 模式下，同一類別連續被阻擋此數次後，下一次將轉為詢問。',
    'settings.permissions.autoTotalLimit.help' => '在 auto 模式下，一個工作階段中已封鎖達此數量後，後續每次封鎖將改為詢問你。',
    'settings.pluginPaths.help' => '除兩個已安裝根目錄外，額外掃描 Claude 格式插件套件的目錄；值可為套件本身或套件容器。僅限使用者層級 — 檢出目錄無法註冊自身插件。',
    'settings.promptCache.keepWarm.help' => '閒置時段允許的暖機 ping 次數；0（預設）為關閉。每次 ping 重新傳送閒置工作階段凍結的前綴，附帶一行指令要求單字元回覆，讓服務商在 TTL 到期前刷新提示快取，使下次提示不必以未快取狀態預填整個對話。僅在 cacheTtl 折減下降時觸發——低於其下限或未到其小時數——於折減監控已執行的同一 tick/alarm 上，絕不在回合中觸發，絕不超過一次，每個時段不超過此數。這些是向無人監看的工作階段發出的計費呼叫；消費上限仍然生效。計數顯示於 /usage 下的 `warm`。',
    'settings.promptCache.help' => '是否由 `vertex` 和 `bedrock` 供應商標記提示快取斷點。',
    'settings.promptSuggestionHistory.help' => '顯示最近的訊息（每則截斷至 2000 字元）及提示建議呼叫。',
    'settings.promptSuggestions.help' => '每輪對話後，向標題模型詢問你接下來可能發送的消息，以灰色顯示在空白輸入框中（→ 接受）。',
    'settings.provider.help' => '工作階段對話的 LLM 供應商；每個提示都會傳送至其主機。',
    'settings.providerRetryAttempts.help' => '每次供應商請求遇暫時性失敗（network、5xx、408、429）時的呼叫次數，含首次；1 表示不重試。',
    'settings.providerRetryBaseBackoffMs.help' => '提供者呼叫失敗後首次重試的等待時間；之後每次加倍。',
    'settings.providers.help' => '各名稱的供應商定義 ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}})；每條目疊加於該類型預設值之上。僅限使用者層級：專案絕不可改變憑證的傳送目的地。',
    'settings.queueMode.help' => 'steer（代理於下一步讀取）、followup（於該回合結束後送出）或 interrupt（於下一步停止該回合，再送出）。Tab 一律排隊。',
    'settings.readMaxBytes.help' => '單次 Read 呼叫的上限；下方頁面為讀取通常回傳的大小。',
    'settings.readPageBytes.help' => '單一 Read 頁面可容納的位元組數，含行號，由 `limit` 決定。',
    'settings.readPageLines.help' => '當呼叫未指定 `limit` 時，Read 傳回的行數。',
    'settings.reasoningEffort.help' => '思考層級依配對關係決定是否送出：openai（o 系列與 gpt-5，不含 -chat 版本）、anthropic 與 vertex（claude-3-7 及更新；vertex 的 claude 與 gemini 端皆會回應）、gemini（2.5 及更新）、sglang（每個請求皆轉送）、bedrock（claude ids，作為思考預算）、codex 與 claude-code（具名層級轉送至 CLI）；未設定或無法辨識則不請求。`/effort` 設定與清除。',
    'settings.redactToolOutput.help' => '預設關閉：已確定的工具輸出會原樣存入歷史記錄與 sessions.db。開啟後，每個工具結果在確定後都會經過與記憶及 `/share` 相同的遮蔽器處理——辨識出的憑證在持久化的位元組中以及後續輪次回放給模型的內容裡都會變成 `[REDACTED]`（工具本身仍照常執行）。圖片、文件與用量欄位原樣通過不受影響。`/export` 不額外遮蔽：它只輸出已儲存的內容，因此開啟此選項前已儲存的資料仍為原始狀態。',
    'settings.references.help' => '工作區外部的 `[{"path": "…", "name": "…"}]` 目錄清單，供 Read、Grep、Glob 與 Ls 唯讀存取；每個目錄會在 `<env>` 區塊中以截斷清單顯示其內容。Write、Edit 與 Bash 的工作區沙箱限制不變——參考目錄不會擴大可寫入範圍。僅限使用者層級：已簽出的儲存庫無法新增唯讀根目錄。路徑不存在、非目錄、或位於工作階段根目錄內者，啟動時將拒絕並顯示提示。',
    'settings.repoMap.enabled.help' => '將程式碼位置對應表（套件與 PSR-4 來源目錄）放入系統提示。',
    'settings.repoMap.maxBytes.help' => 'repo map 兩個區塊各自的位元組預算；超出預算的條目僅計數，不列出。',
    'settings.requireReadBeforeWrite.help' => '開啟時，`Edit`、覆寫既有檔案的 `Write` 及修改、移動或刪除檔案的 `ApplyPatch` 區段，在模型於此工作階段讀取該檔案前一律拒絕；建立新檔案不受阻擋。預設關閉：模型已讀取的檔案仍受磁碟變更規則保護。',
    'settings.resumeCostWarnUsd.help' => '過期恢復後，若重新傳送歷史的未快取成本估計至少達此金額（美元），第一個提示將被暫緩一次；再按 Enter 可強制傳送，或先執行 /compact。0 停用暫緩。',
    'settings.sandboxAllowedDomains.help' => '`allowlist` 沙箱可存取的主機清單：純名稱（`example.com`）、`*.example.com` 萬用字元及 `host:port` 寫法（預設：無）。僅在 Linux 上 `bashSandbox` 設為 `allowlist` 時使用；清單為空時，`allowlist` 行為與 `no-network` 完全相同。出口代理僅允許 HTTP(S)，其他一律拒絕——未列出的主機一律回傳 403，非 HTTP 流量（ssh、資料庫埠）將失敗。格式錯誤的條目在執行時會被忽略：拼寫錯誤只會縮小授權範圍，絕不會擴大。僅限使用者層級：已檢出的儲存庫不得在其所屬沙箱中開啟漏洞。macOS 將 `allowlist` 視為 `no-network` 執行——迴環埠分支為追蹤中的後續項目。',
    'settings.sandboxScope.help' => '工具路徑之外，哪些命令會加入 `bashSandbox` 監獄：`hooks`、`lint`、`format`、`test`、`lsp`、`mcp`（預設：無）。僅在 `bashSandbox` 不為 `off` 時生效——此清單只說明誰共用監獄，不表示監獄是否存在。無法識別的條目視為 EVERY scope（最嚴格，如同無法識別的 `bashSandbox` 值），設定稽核會標記它。無法啟動的監獄會拒絕工作，而非讓其自由執行：script hooks 拒絕，lint、format 和 test 跳過並附原因，被監禁的 LSP 或 MCP stdio server 則不啟動。`lsp` 條目和 user-tier MCP 條目支援逐伺服器 `"sandbox": false` 退出選項；project-tier MCP 的退出選項會被忽略。',
    'settings.screenReader.help' => '給螢幕閱讀器使用者的顯示模式。開啟時，應用程式會移除閱讀器無法朗讀的裝飾——代理載入動畫固定為靜態畫面，方框邊框、僅以反白顯示的選單選取等改為純文字與語音提示，每個介面皆遵循此開關。關閉時，終端機維持一貫的彩色繪製畫面。這是您個人的無障礙設定，如同草稿編輯器的 vim 模式：已簽出的專案無法更改。儲存後下次讀取時生效——即時，無需重新載入。',
    'settings.rules.standingMaxBytes.help' => '位元組預算，已加框與跳脫，用於完整嵌入每個提示的規則檔案；超出預算的規則僅以一行指標名稱代替。',
    'settings.scrollWheelLines.help' => '每格滾輪捲動一行逐字稿。',
    'settings.sd.apiKey.help' => '傳送至 Stable Diffusion 伺服器的 Bearer key（若伺服器要求）；建議使用 `${VAR}` 佔位符格式而非字面值。',
    'settings.sd.baseUrl.help' => '相容於 AUTOMATIC1111 的 Stable Diffusion webui 之 HTTP 基礎 URL（`http://127.0.0.1:7860`）；提示詞、圖片與 API 金鑰皆由此送出。',
    'settings.sd.defaultModel.help' => '模型 ID 產生請求的開頭字元；未設定時由伺服器自行決定。',
    'settings.sd.presets.help' => '媒體表單提供的具名參數包；其結構為媒體管線自有，對設定層不透明。',
    'settings.sd.savePattern.help' => '儲存媒體的檔名範本；`[date]`、`[time]`、`[seed]` 與 `[number]` 標記會在儲存時填入。',
    'settings.sd.timeoutSeconds.help' => '一個生成請求在被放棄前可執行的秒數；在效能較弱的 GPU 上，擴散運算通常需要數分鐘。',
    'settings.secretEnvAllowlist.help' => 'Bash、Grep 與腳本鉤子仍會繼承的憑證樣式變數名稱（或 glob 模式）。',
    'settings.server.allowBypass.help' => '是否允許伺服器工作階段以 bypass-permissions 或 dont-ask 模式執行（同 --allow-bypass）。',
    'settings.server.allowedHosts.help' => '伺服器除迴環名稱與自身位址外，所回應的主機名稱（或 host:port），例如反向代理的名稱。',
    'settings.server.allowedIps.help' => '除迴環外，允許連線的用戶端 IP 或 CIDR 範圍；其他來源在登入前即被拒絕 403。空白：不進行位址篩選。',
    'settings.server.allowedOrigins.help' => '伺服器除自身外所接受的額外瀏覽器來源 (http(s)://host[:port])。',
    'settings.server.askTimeoutSeconds.help' => '權限詢問等待用戶端的秒數，逾時即拒絕；0 表示無限等待。',
    'settings.server.browseRoot.help' => 'server.dirBrowse 限制目錄（同 --browse-root）；未設定則為家目錄。',
    'settings.server.dirBrowse.help' => '讓已登入的用戶端列出 server.browseRoot 下的目錄名稱，並在其中啟動工作階段（同 --allow-dir-browse）。預設關閉。',
    'settings.server.clientTools.help' => '允許 Write-scope 用戶端透過 tools.client.register 註冊工具，讓模型能呼叫在用戶端本身執行的程式碼（client__* 工具）。預設關閉。',
    'settings.server.drainSeconds.help' => '伺服器停止時等待執行中回合的秒數，逾時即取消；0 表示立即停止。',
    'settings.server.host.help' => '`serve` 綁定的位址。非迴環位址啟動時也需要 --allow-remote。',
    'settings.server.maxConcurrentTurns.help' => '伺服器跨所有工作階段同時執行的回合數；超出則以忙碌拒絕（可重試）。',
    'settings.server.maxOpenSessions.help' => '伺服器同時保持開啟的工作階段數；超過時將釋放最久未使用的閒置工作階段。',
    'settings.server.port.help' => '`serve` 綁定的連接埠；0 表示自動選取可用埠',
    'settings.server.trustedProxies.help' => '伺服器信任其 X-Forwarded-For / X-Forwarded-Proto 的 IP 或 CIDR 範圍。',
    'settings.serviceTier.help' => '高級通道依配對設定自動路由：openai 在 Chat 與 Responses 兩端皆要求 `service_tier: "priority"`，anthropic 要求 `speed: "fast"`（僅限 claude-opus-5-5 GA 系列與 claude-opus-5 / claude-opus-4-8 research-preview 系列，其必要 beta header 自動附加）；未設定或無法辨識時不要求任何參數。快速模式計費為高級費率，無法由模型對應價格表推算：分級配對運作期間，其對話回合以未定價記錄於帳務，絕不以推估費率入帳。啟動時及每次 provider 或 model 重建時皆適用。',
    'settings.sessionRetentionDays.help' => '每次啟動會刪除超過此天數未使用的未命名、未釘選會話，並告知哪些；0（預設值）保留全部。',
    'settings.sessions.autoTitle.help' => '透過一次標題模型呼叫，從第一輪對話為每個新工作階段命名；關閉則保持未命名，直到 /rename。',
    'settings.sessions.awayRecap.help' => '終端機重新取得焦點且離開超過三分鐘時，印出一段會話進度摘要（每次離開僅呼叫一次標題模型）；off 則返回時保持靜音。`/recap` 可隨時要求摘要。',
    'settings.skills.listingMaxBytes.help' => '系統提示中完整技能清單的位元組預算；超出預算的技能將收合為一行 "N more skills"。',
    'settings.skills.pathNudges.help' => '當工具存取路徑限定技能涵蓋的檔案時，提醒模型該技能存在，每個技能僅一次。',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}：輸出繪製狀態列的 shell 指令，每 refreshSeconds 秒重新執行（2 至 3600，預設 2）。透過 stdin 接收一份 JSON 文件形式的 session（session_id、cwd、model、workspace、version、cost，以及 candy_code 額外欄位）；即使指令不讀取 stdin 仍會執行。',
    'settings.streamHeaderTimeoutSeconds.help' => '已連線串流伺服器送出回應標頭所需的秒數；非總請求逾時。',
    'settings.streamIdleTimeoutSeconds.help' => '串流回應單次讀取等待位元組的秒數，逾時即判定連線失效；每次讀取獨立計算，非累計總時間。',
    'settings.subagentMaxActive.help' => '單一工作階段同時可執行的委派執行數，計入所有層級、成員與背景代理；超過後 `Task` 呼叫將被拒絕。未設定（預設值）或 0 表示無上限。',
    'settings.subagentMaxConcurrent.help' => '一批同時執行的 `Task` 呼叫數（其餘等待空閒槽位），以及每個 agent 池的寬度。未設定（預設值）或 0 表示無上限。',
    'settings.subagentMaxDepth.help' => '委派執行可低於工作階段的層級數；位於最後一層的執行不會取得 `Task`。設為 1 時，子代理無法再委派。',
    'settings.subagentMaxTurns.help' => '子代理的步驟上限——即 `Task` 委派、工作流程階段或 `executeAgents` 執行——其預設未宣告 `maxTurns`。',
    'settings.subagentModel.help' => '委派子代理的預設寫 `inherit` 時所採用的模型；未設定則跟隨工作階段模型。',
    'settings.summaryModel.help' => '撰寫壓縮摘要的模型；未設定則使用對話本身的模型，可重用提示快取。',
    'settings.symbolMap.enabled.help' => '將排名後的符號層級倉庫地圖放入系統提示，每個工作階段僅擷取一次。',
    'settings.temperature.help' => '請求未指定時，`custom` 供應商發送的取樣溫度。',
    'settings.terminalBackground.help' => '自適應主題對文字背景的假設：auto 詢問終端機（OSC 11，再 COLORFGBG）；light 或 dark 直接指定。',
    'settings.testCommand.help' => '在專案根目錄執行測試的 shell 指令（`composer test`、`pytest -q`）；即 `autoTest` 所執行的指令。',
    'settings.theme.help' => '色彩主題；/theme 與調色盤可即時切換。自訂主題從 ~/.candy-code/themes 下的 JSON 檔案載入。',
    'settings.thinkingBudget.help' => '思考權元預算：`vertex` 供應商上的 Gemini `thinkingConfig`；`anthropic` 供應商上的延伸思考，Messages API 下限為 1024（0 或未設定表示兩端皆關閉）。思考權元計為輸出。',
    'settings.titleModel.help' => '為工作階段命名並撰寫提示建議的模型；未設定則使用供應商類型的廉價輔助預設，優先於區塊模型。',
    'settings.transcriptJsonl.help' => '將每份已提交的逐字稿鏡像寫入 `~/.candy-code/transcripts/<project>/` 下的僅附加 JSONL 日誌（檔案權限 0600），並向 hook 腳本提供指向該日誌的 `transcript_path` stdin 鍵。日誌儲存原始對話且無限增長；啟動時讀取，因此變更於下次啟動生效。',
    'settings.toolInstructionCapBytes.help' => 'Edit、Write 或 ApplyPatch 結果可攜帶的 CLAUDE.md/AGENTS.md 主體最大位元組數；超出部分以標記截斷。',
    'settings.toolOutputCapBytes.help' => '單一 Bash、Grep、Glob、Lsp 或 WebFetch 結果可交給模型的最大位元組數；截斷部分儲存至結果所命名的檔案。',
    'settings.toolOutputPreviewLines.help' => '逐字稿中顯示的摺疊工具結果行數；Ctrl+O 展開其餘部分。',
    'settings.toolSpillCaptureBytes.help' => 'Bash 指令輸出（每串流）保留於記憶體並寫入溢位檔案的最大量（結果截斷時）；不得低於輸出上限。',
    'settings.toolSpillMinCapBytes.help' => '截斷工具結果寫入檔案的最小結果上限；低於此值則僅公告截斷並丟棄其餘。',
    'settings.toolSpillWindowPercent.help' => '單一工具結果可佔用的上下文視窗最大比例；超出則結果寫入檔案，模型僅見其開頭與結尾。',
    'settings.trustedProjectCommands.help' => '允許斜線指令執行 !`cmd` shell 區塊的專案根目錄。',
    'settings.trustedProjectHooks.help' => '允許執行 .candy-code/hooks.yaml 的專案根目錄。',
    'settings.trustedProjectMcp.help' => '允許啟動 .mcp.json 伺服器的專案根目錄。',
    'settings.trustedProjectSettings.help' => '允許設定專案層級鍵值的 .candy-code/settings*.json 所在專案根目錄。',
    'settings.turnIdleTimeoutSeconds.help' => '執行中的回合無任何進度後判定為掛起並停止的秒數；為閒置時間，非總時間。',
    'settings.ui.imageRenderMode.help' => '終端機中繪製生成圖片的方式；`auto` 選擇終端機回報的最佳協定。',
    'settings.ui.mediaDisplayOverrides.help' => '各渲染模式的顯示調整（大小上限、備援）；鍵為渲染模式名稱，值為顯示參數。',
    'settings.vimMode.help' => '草稿框中的 NORMAL/INSERT 編輯模式（i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, text objects di\" da( ciw, counts 3dd d2w）：NORMAL 模式下的移動、修改、刪除與複製，INSERT 模式下的逐字輸入。這是一種模式而非鍵位綁定——不會出現在 /keys 中。儲存後於下一次按鍵生效。',
    'settings.voice.apiKey.help' => '若轉錄端點要求則發送的 Bearer 金鑰；建議使用 `${VAR}` 佔位符形式而非明文。',
    'settings.voice.baseUrl.help' => 'OpenAI 相容轉錄端點的 HTTP 基礎 URL（尾端的 `/v1` 保留）；錄音僅傳送至該處。無預設值：使用者層級設定此項前，語音輸入保持 OFF。',
    'settings.voice.language.help' => '強制指定轉錄語言的 BCP-47 代碼（`en`、`de`）；未設定則由端點自行偵測。',
    'settings.voice.maxSeconds.help' => '單次錄音的硬性秒數上限（5-600，預設 120）。上限隨錄音器參數傳遞，因此孤立的錄音會自行停止。',
    'settings.voice.model.help' => '每次轉錄請求發送的模型 ID；`whisper-1` 適用於 OpenAI 相容端點。',
    'settings.watchFiles.help' => '當儲存的檔案含有以 AI!（進行修改）或 AI?（回答問題）結尾的註解時發送提示；一般 AI 註解作為上下文附帶。閒置時輪詢；僅啟動後儲存的註解觸發，各一次。僅限終端機工作階段：監看器在終端機程序中執行，因此由 `candy-code serve` 託管的工作階段不監看檔案。',
    'settings.webFetchMaxBytes.help' => '抓取內容保留於記憶體的最大量；為記憶體限制，輸出上限才是送達模型的量。',
    'settings.webFetchTimeoutSeconds.help' => 'WebFetch 套接字讀取停滯後判定抓取失敗的秒數。',
    'settings.webSearchBackend.help' => 'WebSearch 查詢的搜尋服務：`searxng`（預設）將所有查詢送至設定的 `webSearchEndpoint`；`brave`、`tavily` 和 `exa` 則連線該服務的固定主機，且各自需在環境中設定 API 金鑰（`BRAVE_SEARCH_API_KEY`、`TAVILY_API_KEY`、`EXA_API_KEY`），無法指向其他 URL。',
    'settings.webSearchEndpoint.help' => '信任的 SearXNG 實例搜尋 URL（`https://searx.example.org/search`）；所有 WebSearch 查詢均送至該處。',
    'settings.webSearchMaxResults.help' => '單一 WebSearch 摘要列出的結果數，每項含標題、URL 與摘要片段。',
    'settings.webSearchTimeoutSeconds.help' => '單一搜尋請求可耗費的秒數。',
    'settings.webhooks.help' => '鉤子名稱對應 {secret, prompt, permissionMode?, rate?} 的映射；POST /api/hooks/{name} 將請求主體（以不可信方式轉義）拼入提示並啟動背景工作階段。空白（預設）不掛載任何內容。rate 為每地址每分鐘 N 次投遞，以及每鉤子整體上限。啟動時拒絕鉤子的 bypass-permissions；無模式的鉤子以伺服器模式與預設中較嚴格者執行。列項亦可指定 signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}：路由則透過 signature 標頭以列項 secret 驗證原始主體的 HMAC-SHA256（sha256=<hex>），取代自訂標頭 secret，因 GitHub 無法發送自訂標頭；驗證失敗計入同一每鉤子鎖定，且已見過的投遞 ID（GitHub 方案預設為 X-GitHub-Delivery；通用方案為設定的 deliveryHeader）回傳 {"ok": true, "duplicate": true} 而不啟動第二個工作階段。',
    'settings.webhooksOut.help' => '端點名稱對應 {url, secret, events} 的映射；events 為從 turn.completed、session.ended、permission.asked 和 schedule.fired 中選取的非空清單。空白（預設）不開啟任何出站通道。僅從 USER 層級讀取——專案或 bundle 設定永遠無法新增出站端點。url 必須為 https，僅當字面主機為 localhost 或回環位址時可用 http，且絕不攜帶 userinfo；secret 至少 16 字元，以 HMAC-SHA256 對每次投遞簽名為 X-Candy-Code-Signature（sha256=<hex> 基於確切主體）並搭配 X-Candy-Code-Timestamp。投遞在事件迴圈上非同步執行——派遣從不等待回應：2 秒連線邊界與每次 POST 10 秒網路上限約束每次投遞（webhook 限制，非 LLM 請求逾時），傳輸失敗與 5xx 回應沿 2/8/30 秒重試階梯遞增，4xx 與重定向回應首次即為最終結果（因拒絕而非跟隨重定向），且 128 個進行中投遞的有界佇列在溢位時丟棄新派遣而非增長記憶體。啟動時讀取；變更映射於重啟後生效。',
    'settings.webhooksOut.refuse' => '使用者設定中的 webhooksOut 不可用：{reason}。拒絕啟動而非投遞至未完全驗證的端點——修正映射，或移除該鍵以不帶出站 webhook 執行。',
    // --- end settings help ---

